"""FastAPI app: intake, approve and list routes (contract section 7)."""
import hashlib
import hmac
import json

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

from app.db import connect, init_db


def _err(code: int, msg: str) -> JSONResponse:
    return JSONResponse(status_code=code, content={"detail": msg})


def create_app(db_path: str | None = None) -> FastAPI:
    app = FastAPI()
    setup = connect(db_path)
    init_db(setup)
    setup.close()

    def db():
        return connect(db_path)

    @app.post("/webhooks/notices")
    async def intake(request: Request):
        raw = await request.body()
        try:
            payload = json.loads(raw)
        except (ValueError, UnicodeDecodeError):
            return _err(400, "invalid json")
        if not isinstance(payload, dict):
            return _err(400, "body must be an object")
        for field in ("notice_id", "inbox", "text"):
            if not isinstance(payload.get(field), str):
                return _err(400, f"{field} missing or not a string")

        conn = db()
        try:
            tenant = conn.execute(
                "SELECT tenant_id, secret FROM tenants WHERE inbox = ?",
                (payload["inbox"],),
            ).fetchone()
            if tenant is None:
                return _err(404, "unknown inbox")

            sig = request.headers.get("X-Signature")
            expected = hmac.new(
                tenant["secret"].encode(), raw, hashlib.sha256
            ).hexdigest()
            if sig is None or not hmac.compare_digest(sig.lower(), expected):
                return _err(403, "bad signature")

            conn.execute(
                "INSERT INTO notices(tenant_id, notice_id, text, status) "
                "VALUES (?, ?, ?, 'received') "
                "ON CONFLICT(tenant_id, notice_id) DO NOTHING",
                (tenant["tenant_id"], payload["notice_id"], payload["text"]),
            )
            return {"ok": True}
        finally:
            conn.close()

    @app.post("/tenants/{tenant}/notices/{notice_id}/approve")
    def approve(tenant: str, notice_id: str):
        conn = db()
        try:
            conn.execute("BEGIN IMMEDIATE")
            try:
                if conn.execute(
                    "SELECT 1 FROM tenants WHERE tenant_id = ?", (tenant,)
                ).fetchone() is None:
                    conn.execute("ROLLBACK")
                    return _err(404, "unknown tenant")
                row = conn.execute(
                    "SELECT id, status, matter_id, filed_date FROM notices "
                    "WHERE tenant_id = ? AND notice_id = ?",
                    (tenant, notice_id),
                ).fetchone()
                if row is None:
                    conn.execute("ROLLBACK")
                    return _err(404, "notice not found")
                if row["status"] == "docketed":
                    conn.execute("ROLLBACK")
                    return {"notice_id": notice_id, "status": "docketed"}
                if row["status"] in ("received", "processing") or row["matter_id"] is None:
                    conn.execute("ROLLBACK")
                    return _err(409, "notice not ready for approval")
                conn.execute(
                    "INSERT INTO calendar_entries(notice_pk, tenant_id, matter_id, filed_date) "
                    "VALUES (?, ?, ?, ?) ON CONFLICT(notice_pk) DO NOTHING",
                    (row["id"], tenant, row["matter_id"], row["filed_date"]),
                )
                conn.execute(
                    "UPDATE notices SET status = 'docketed', needs_review = 0 "
                    "WHERE id = ? AND tenant_id = ?",
                    (row["id"], tenant),
                )
                conn.execute("COMMIT")
                return {"notice_id": notice_id, "status": "docketed"}
            except Exception:
                if conn.in_transaction:
                    conn.execute("ROLLBACK")
                raise
        finally:
            conn.close()

    @app.get("/tenants/{tenant}/notices")
    def list_notices(tenant: str):
        conn = db()
        try:
            if conn.execute(
                "SELECT 1 FROM tenants WHERE tenant_id = ?", (tenant,)
            ).fetchone() is None:
                return _err(404, "unknown tenant")
            rows = conn.execute(
                "SELECT notice_id, matter_id, filing_type, filed_date, needs_review, status "
                "FROM notices WHERE tenant_id = ? ORDER BY id",
                (tenant,),
            ).fetchall()
            return [
                {
                    "notice_id": r["notice_id"],
                    "matter_id": r["matter_id"],
                    "filing_type": r["filing_type"],
                    "filed_date": r["filed_date"],
                    "needs_review": bool(r["needs_review"]),
                    "status": r["status"],
                }
                for r in rows
            ]
        finally:
            conn.close()

    return app

"""The ONE validation path shared by the worker and evals (contract sections 4 and 5)."""
import datetime
import re
from typing import Callable

from app.constants import FILING_TYPES
from app.db import matter_ids
from extractor import extract

Extractor = Callable[[str], object]

KEYS = ("filing_type", "matter_id", "filed_date")
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _invalid() -> dict:
    return {"matter_id": None, "filing_type": None, "filed_date": None, "needs_review": True}


def _real_date(value: str) -> bool:
    if not _DATE_RE.match(value):
        return False
    try:
        datetime.date.fromisoformat(value)
    except ValueError:
        return False
    return True


def check(answer: object, tenant_id: str, conn) -> dict:
    """Validate an extractor answer for one tenant. Never raises."""
    try:
        if not isinstance(answer, dict):
            return _invalid()
        if any(k not in answer for k in KEYS):
            return _invalid()
        filing_type = answer["filing_type"]
        matter_id = answer["matter_id"]
        filed_date = answer["filed_date"]
        if not isinstance(filing_type, str) or filing_type not in FILING_TYPES:
            return _invalid()
        if matter_id is not None:
            if not isinstance(matter_id, str) or matter_id not in matter_ids(conn, tenant_id):
                return _invalid()
        if filed_date is not None:
            if not isinstance(filed_date, str) or not _real_date(filed_date):
                return _invalid()
        return {
            "matter_id": matter_id,
            "filing_type": filing_type,
            "filed_date": filed_date,
            "needs_review": matter_id is None,
        }
    except Exception:
        return _invalid()


def run_extraction(text: str, tenant_id: str, conn, extractor: Extractor = extract) -> dict:
    """check(extractor(text), tenant_id, conn); an extractor exception is an invalid answer."""
    try:
        answer = extractor(text)
    except Exception:
        return _invalid()
    return check(answer, tenant_id, conn)

"""`python -m evals`: run run_extraction over evals/notices.jsonl and report per-field accuracy.

Exit codes: 0 all fields >= 0.90, 1 some field below, 2 data file missing or malformed.
"""
import json
import sys
from pathlib import Path

from app.db import connect, init_db
from worker.checks import run_extraction

FIELDS = ("filing_type", "matter_id", "filed_date")
THRESHOLD = 0.90
DATA = Path(__file__).resolve().parent / "notices.jsonl"


def load(path: Path) -> list[dict]:
    cases = []
    for lineno, line in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        if not line.strip():
            continue
        try:
            case = json.loads(line)
            _ = (case["id"], case["tenant"], case["text"])
            _ = [case["expected"][f] for f in FIELDS]
        except (ValueError, KeyError, TypeError) as exc:
            raise ValueError(f"{path.name}:{lineno}: bad eval line ({exc!r})") from exc
        cases.append(case)
    return cases


def main(path: Path = DATA) -> int:
    if not path.is_file():
        print(f"error: eval data not found: {path}", file=sys.stderr)
        return 2
    try:
        cases = load(path)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    if not cases:
        print(f"error: no eval cases in {path}", file=sys.stderr)
        return 2

    conn = connect(":memory:")
    init_db(conn)
    correct = {f: 0 for f in FIELDS}
    for case in cases:
        result = run_extraction(case["text"], case["tenant"], conn)
        misses = [f for f in FIELDS if result[f] != case["expected"][f]]
        for f in FIELDS:
            if f not in misses:
                correct[f] += 1
        if misses:
            got = {f: result[f] for f in misses}
            want = {f: case["expected"][f] for f in misses}
            print(f"MISS {case['id']}: got {got} want {want}")

    n = len(cases)
    failed = False
    for f in FIELDS:
        acc = correct[f] / n
        flag = "ok" if acc >= THRESHOLD else "BELOW 0.90"
        failed |= acc < THRESHOLD
        print(f"{f:<12} {correct[f]}/{n} = {acc:.2f} {flag}")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())
